# Verifying independence of two events using Python 3.13+
# Event A: Rolling an even number on a die
# Event B: Rolling a number greater than 4 (5 or 6)

sample_space = {1, 2, 3, 4, 5, 6}
event_a = {2, 4, 6}
event_b = {5, 6}

p_a = len(event_a) / len(sample_space)
p_b = len(event_b) / len(sample_space)

intersection = event_a.intersection(event_b) # {6}
p_intersection = len(intersection) / len(sample_space)

product_p = p_a * p_b
print(f"P(A) * P(B): {product_p:.4f}")
print(f"P(A ∩ B): {p_intersection:.4f}")

if abs(p_intersection - product_p) < 1e-9:
    print("Events A and B are Independent.")
else:
    print("Events A and B are NOT Independent.")

