def calculate_pmf_dict(outcomes_list):
    total = len(outcomes_list)
    return {k: v / total for k, v in __import__('collections').Counter(outcomes_list).items()}

def variance_discrete(pmf_dict):
    mean = sum(x * p for x, p in pmf_dict.items())
    mean_sq = sum((x ** 2) * p for x, p in pmf_dict.items())
    return mean_sq - (mean ** 2)

import numpy as np

def simulate_geometric(p, runs=10000):
    # np.random.geometric returns the number of trials needed
    trials = np.random.geometric(p, size=runs)
    return np.mean(trials)

