def find_high_corr(df, threshold=0.85):
    corr = df.corr()
    high_pairs = []
    for i in range(len(corr.columns)):
        for j in range(i):
            if abs(corr.iloc[i, j]) >= threshold:
                high_pairs.append((corr.columns[i], corr.columns[j], corr.iloc[i, j]))
    return high_pairs

import pandas as pd
def drop_correlated_features(df, threshold=0.9):
    corr_matrix = df.corr().abs()
    upper = corr_matrix.where(pd.np.triu(pd.np.ones(corr_matrix.shape), k=1).astype(bool))
    to_drop = [col for col in upper.columns if any(upper[col] > threshold)]
    return df.drop(columns=to_drop)

import math
def find_k_for_probability(target_prob):
    # P <= 1/k^2 => k = 1 / sqrt(target_prob)
    return 1.0 / math.sqrt(target_prob)

def chebyshev_interval(mu, sigma, k):
    lower = mu - (k * sigma)
    upper = mu + (k * sigma)
    min_prob = 1 - (1 / (k ** 2))
    return (lower, upper, min_prob)

import math
def binomial_pmf(n, k, p):
    comb = math.comb(n, k)
    return comb * (p ** k) * ((1 - p) ** (n - k))

def binomial_cdf(n, k, p):
    import math
    return sum(math.comb(n, i) * (p ** i) * ((1 - p) ** (n - i)) for i in range(k + 1))

def binomial_mode(n, p):
    import math
    return math.floor((n + 1) * p)

