# Joint PDF f(x, y) = e^{-x - y} for x >= 0, y >= 0
def joint(x, y):
    import math
    return math.exp(-x - y)

# Marginal f_Y(y) = int_0^inf e^{-x-y} dx = e^{-y}
def marginal_y(y):
    import math
    return math.exp(-y)

# Conditional density f_{X|Y}(x|y) = joint / marginal_y
def conditional_x_given_y(x, y):
    return joint(x, y) / marginal_y(y)

print(f"Conditional density f(X=1 | Y=1): {conditional_x_given_y(1, 1):.4f}")
# Since X and Y are independent here, f(X=1|Y=1) equals f_X(1) = e^{-1} \approx 0.3679

